Ltac fp_dec :=
      lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
        lazymatch c with context [reg_get] => fail "open FP condition" | _ => idtac end;
        let w := eval vm_compute in c in change c with w; cbv iota end.
Ltac fs_walk :=
        repeat first [ reflexivity
                     | progress (rewrite ?fs_reg_get_set; fs_eqb_simp)
                     | match goal with H : fs_agree ?F1 ?F2 |- context [reg_get ?F2 ?r] => rewrite (fs_agree_get F1 F2 r H) by reflexivity end ].
Ltac fs_agree_chain :=
        let r := fresh "r" in let Hr := fresh "Hr" in
        intros r Hr; apply fs_callee_cases in Hr; cbn [map In] in Hr;
        repeat (destruct Hr as [<-|Hr]); [..| destruct Hr]; fs_walk.
